#include <stdio.h>
#include <string.h>

int characterReplacement(const char* s, int k) {
    int count[26] = {0}, left = 0, maxCount = 0, best = 0;
    int n = (int)strlen(s);
    for (int right = 0; right < n; ++right) {
        int idx = s[right] - 'A';
        ++count[idx];
        if (count[idx] > maxCount) maxCount = count[idx];
        while ((right - left + 1) - maxCount > k) {
            --count[s[left] - 'A'];
            ++left;
        }
        int window = right - left + 1;
        if (window > best) best = window;
    }
    return best;
}

